function appendixRows(ctx) {
  const res = {};
  for (const L of ['A', 'B', 'C', 'D', 'E']) {
    let sec = null; let hdr = null;
    for (const l of ctx.read(AP(L)).split('\n')) {
      const m = l.match(/^###\s+(\S+)\.md/);
      if (m) { sec = m[1]; hdr = null; continue; }
      if (/^#/.test(l)) { sec = null; hdr = null; continue; }
      if (!sec) continue;
      if (!l.startsWith('|')) { hdr = null; continue; }
      const cells = l.split('|').slice(1, -1).map((s) => s.trim());
      if (!hdr) { hdr = cells; continue; }
      if (/^:?-+:?$/.test(cells[0])) continue;
      const mi = hdr.findIndex((h) => /match/i.test(h));
      if (mi < 0) continue;
      (res[sec] ??= []).push(cells[mi].replace(/\*/g, ''));
    }
  }
  return res;
}

async function run(ctx) {
  const out = {};
  const ap = appendixRows(ctx);
  out['d-audit-docs'] = `All ${Object.keys(ap).length} docs`;
  const isMatch = (v) => /^(yes|Y)\b/.test(v) && !/^yes at commit/.test(v);
  let R = 0; let M = 0;
  for (const [, d] of T1) {
    const rows = ap[d] ?? [];
    out[`d-audit-t1-${sid(d)}-rows`] = String(rows.length);
    out[`d-audit-t1-${sid(d)}-match`] = String(rows.filter(isMatch).length);
    R += rows.length; M += rows.filter(isMatch).length;
  }
  out['d-audit-t1-total-rows'] = String(R);
  out['d-audit-t1-total-match'] = String(M);
  // column totals of the doc's own (not-checkable) split, and the per-row identity mis+amb+nc = rows - match
  const consistent = T1.every(([, , rows, match, mis, amb, nc]) => mis + amb + nc === rows - match);
  const col = (i) => T1.reduce((a, r) => a + r[i], 0);
  out['d-audit-t1-total-mismatch'] = consistent ? String(col(4)) : 'rows inconsistent';
  out['d-audit-t1-total-ambiguous'] = consistent ? String(col(5)) : 'rows inconsistent';
  out['d-audit-t1-total-nc'] = consistent ? String(col(6)) : 'rows inconsistent';
  out['d-audit-e7-rows'] = { 3: 'three totals' }[(ap['v1.3-labelling-2026-10-15'] ?? []).filter((v) => v === 'N').length] ?? '?';

  // findings register (lines 75-103)
  const reg = ctx.read(DOC).split('\n').slice(74, 103).filter((l) => /^\| [A-E]-\d+ \|/.test(l)).map((l) => l.split('|').map((s) => s.trim()));
  out['d-audit-findings'] = `${reg.length} findings`;
  const mr = reg.filter((r) => r[6] === 'missing raw file' || r[6].startsWith('missing raw file')).map((r) => r[1]);
  out['d-audit-missing-raw'] = mr.length === 4 ? `Four (${mr.join(', ')})` : `${mr.length} (${mr.join(', ')})`;
  out['d-audit-medium'] = { 2: 'The two with medium severity' }[reg.filter((r) => /medium\*\*$|^\*\*medium/.test(r[7]) && !/low/.test(r[7])).length] ?? String(reg.filter((r) => /medium/.test(r[7])).length);
  const plan = ctx.json('experiments/e1-grid/plan.json').e1;
  out['d-audit-e1-outcomes'] = `the ${plan.models.length * plan.specLevels.length * plan.tasks.length * plan.runs} E1 outcome projects`;

  // A-1, A-2, A-4, B-1, E-5, E-7 from raw
  const so4 = ctx.json('results/v1.3-fidelity/so4/aggregate.json').variants['apg-v12e-default'].agreement;
  out['d-audit-a1-raw'] = `Raw: ${so4['tsc.raw'].projectsBelow095.refCoveredByApg} projects against tsc, ${so4['depcruise.raw'].projectsBelow095.refCoveredByApg} against dependency-cruiser`;
  const sc = [so4['tsc.scoped'].projectsBelow095, so4['depcruise.scoped'].projectsBelow095].flatMap((x) => [x.refCoveredByApg, x.apgConfirmedByRef]);
  out['d-audit-a1-scoped'] = `${Math.min(...sc)}–${Math.max(...sc)} is the **scoped** count`;
  const pj = ctx.json('results/v1.3-fidelity/e1/projects/claude-opus-5-5__task-management__none__run-1.json').classes['apg-v12e-default'].tsc;
  out['d-audit-a2'] = `${pj['missing-in-ref:re-export/barrel']} and ${pj['missing-in-apg:re-export/barrel']}`;
  let tr = 0; let ta = 0;
  for (const f of ctx.ls('results/v1.3-fidelity/e1/projects').filter((x) => x.endsWith('.json'))) {
    const c = ctx.json(`results/v1.3-fidelity/e1/projects/${f}`).classes?.['apg-v12e-default']?.tsc ?? {};
    tr += c['missing-in-ref:re-export/barrel'] ?? 0; ta += c['missing-in-apg:re-export/barrel'] ?? 0;
  }
  const cells = ctx.json('results/v1.3-ise-e1/cells.json').filter((c) => c.level === 'none' && c.ise.confidence === 1);
  const di = cells.filter((c) => c.ise.evidence.some((e) => /^\+2 dependency inversion/.test(e))).length;
  out['d-audit-a4'] = `${di} have the +2. ${cells.length - di} cells reach 1.00 on tokens alone`;
  out['d-audit-b1-wilson'] = ctx.f2(ctx.wilson(19, 19)[0]);
  const scg = ctx.csv('results/v1.3-study1-rerun/so4/seed_changes.csv').find((r) => r.seed_id === 'truthy-demo:MO-X01:0');
  const fns = JSON.parse(scg.v13_undeclared_new).map((s) => JSON.parse(s)[0]);
  out['d-audit-e5'] = `${fns.length} (${fns.join(' and ')})`;
  const cr = ctx.json('results/v1.3-labelling/reference/correctness-all/correctness.json').summary;
  const ce = ctx.json('results/v1.3-labelling/e1/correctness-all/correctness.json').summary;
  const s = (a, k) => a.reduce((x, r) => x + r[k], 0);
  const fmt = (x) => x.toLocaleString('en-US');
  out['d-audit-e7'] = `**${fmt(s(cr, 'correct'))} / ${fmt(s(cr, 'notCheckable'))} / ${fmt(s(cr, 'correct') + s(ce, 'correct'))}**`;

  // appendix consistency for the other register values
  for (const [id, , , stated, L, res] of FREG) {
    const t = ctx.read(AP(L));
    let ok = res.every((r) => r.test(t));
    if (id === 'a2-totals') ok = ok && tr === 28 && ta === 11; // also recount the E1 corpus totals
    out[`d-audit-f-${id}`] = ok ? stated : `not found in appendix ${L}`;
  }

  // judge cassettes: 3 runs per unit
  let units = 0; let threeRuns = true;
  for (const d of ['judge-catch', 'judge-catch-round2', 'judge-catch-duprule-v2']) {
    const base = `tests/fixtures/judge-cassettes-v13/${d}`;
    const runs = new Map();
    for (const sub of ctx.ls(base)) for (const f of readdirSync(ctx.p(`${base}/${sub}`))) { const k = f.replace(/-r\d+-\d+\.json$/, ''); runs.set(k, (runs.get(k) ?? 0) + 1); }
    units += runs.size; if ([...runs.values()].some((v) => v !== 3)) threeRuns = false;
  }
  out['d-audit-judged-units'] = threeRuns ? `all ${units} judged units` : `${units} units, not all with 3 runs`;
  const ga = ctx.json('results/v1.3-reference/baseline-pre-barrel/graph/graph-agreement.json').vsBlind;
  const both = ga.reduce((a, r) => a + r.literal.both, 0);
  out['d-audit-blind-edges'] = `${both}/${both + ga.reduce((a, r) => a + r.literal.onlyRef, 0)}`;
  out['d-audit-blind-layers'] = `${ga.reduce((a, r) => a + r.layer.agree, 0)}/${ga.reduce((a, r) => a + r.layer.total, 0)}`;
  const via = ga.reduce((a, r) => a + (r.viaReExport.inTool ?? 0), 0); const viaN = ga.reduce((a, r) => a + (r.viaReExport.refEdges ?? 0), 0);
  out['d-audit-blind-barrel'] = `${via}/${viaN}`;

  // §4 personal-path scan
  const files = (dir, filt = () => true) => ctx.ls(dir).filter(filt).map((f) => `${dir}/${f}`);
  const count = (f, re) => (ctx.read(f).match(re) ?? []).length;
  const lines = (f, re) => ctx.read(f).split('\n').filter((l) => re.test(l)).length;
  const VOL = /\/Volumes\//g; const VOL1 = /\/Volumes\//;
  const fid = [...files('results/v1.3-fidelity/e1/projects', (f) => f.endsWith('.json')), ...files('results/v1.3-fidelity/so4/projects', (f) => f.endsWith('.json'))];
  const fidHit = fid.filter((f) => VOL1.test(ctx.read(f)));
  out['d-audit-p-fid-files'] = `(${fidHit.length} files)`;
  out['d-audit-p-fid-occ'] = String(fidHit.reduce((a, f) => a + count(f, VOL), 0));
  out['d-audit-p-e1jobs'] = `${lines('results/v1.3-labelling/e1/jobs.json', VOL1)} lines`;
  out['d-audit-p-refjobs'] = `${lines('results/v1.3-labelling/reference/jobs.json', /\/Volumes\/|\/private\/tmp\//)} lines`;
  const gh = files('results/v1.3-study1-rerun/so4/case/reports', (f) => f.endsWith('.json')).filter((f) => VOL1.test(ctx.read(f)));
  out['d-audit-p-ghost-files'] = gh.every((f) => /ghostfolio-test/.test(f)) ? `(${gh.length} files)` : `(${gh.length} files, not all ghostfolio)`;
  const per = [...new Set(gh.map((f) => lines(f, VOL1)))];
  out['d-audit-p-ghost-lines'] = per.length === 1 ? `${per[0]} lines each` : per.join('/');
  const v2 = files('results/so4-heldout/v2/case/reports', (f) => f.endsWith('.json')).filter((f) => VOL1.test(ctx.read(f)));
  out['d-audit-p-ghost-v2'] = v2.length === 0 ? 'the v2 reports have none' : `${v2.length} v2 reports`;
  const bar = ctx.ls('results/v1.3-barrels/fidelity').flatMap((d) => (ctx.exists(`results/v1.3-barrels/fidelity/${d}/projects`) ? files(`results/v1.3-barrels/fidelity/${d}/projects`, (f) => f.endsWith('.json')) : [])).filter((f) => VOL1.test(ctx.read(f)));
  out['d-audit-p-barrels-files'] = `(${bar.length} files)`;
  out['d-audit-p-barrels-occ'] = String(bar.reduce((a, f) => a + count(f, VOL), 0));
  out['d-audit-paths-total'] = `About ${fidHit.length + 1 + 1 + gh.length + bar.length}`;

  // hand replays named in appendix B
  const b = ctx.read(AP('B'));
  out['d-audit-hand-toolgraphs'] = /tool-graphs\.json ×3 \(at 89e79f49, 3e8d4b48, 3e2c96ae\)/.test(b) ? '×3' : 'not in appendix B';
  out['d-audit-hand-reports'] = /report\.\* metrics and comparisons ×4/.test(b) ? '×4' : 'not in appendix B';

  // ISE unit tests (A-3), in a scratch export of the audit's commit (the doc's "at HEAD")
  const j = ctx.sh('npx jest --maxWorkers=2 --forceExit tests/unit/ise tests/unit/scripts/v1.3/ise- 2>&1', { cwd: treeAt(ctx, AUDIT_COMMIT) });
  out['d-audit-a3-head'] = `${(j.match(/Tests:\s+(?:\d+ \w+, )*(\d+) total/) ?? [])[1]} at HEAD`;

  return out;
}

async function runSmoke(ctx) {
  const out = {};
  // smoke.sh at HEAD (it exports git archive HEAD itself and never writes the working tree)
  const tmp = ctx.out('d-audit-smoke');
  const log = ctx.sh(`TMPDIR="${tmp}" bash replication/smoke.sh 2>&1; echo "SMOKE_EXIT=$?"`, { timeout: 40 * 60_000 });
  const tally = {}; let sec = '';
  for (const l of log.split('\n')) {
    if (l.startsWith('== ')) { sec = l.slice(3); continue; }
    const m = l.match(/^(IDENTICAL|KNOWN|DIFF|MISSING|EXTRA)\s/);
    if (m) { (tally[sec] ??= {}); tally[sec][m[1]] = (tally[sec][m[1]] ?? 0) + 1; }
  }
  const pick = (re) => Object.entries(tally).filter(([k]) => re.test(k)).map(([, v]) => v);
  const add = (list) => list.reduce((a, v) => { for (const [k, x] of Object.entries(v)) a[k] = (a[k] ?? 0) + x; return a; }, {});
  const tot = (v) => Object.values(v).reduce((a, x) => a + x, 0);
  const verdict = (v) => (Object.keys(v).length === 1 && v.IDENTICAL ? 'IDENTICAL' : ['IDENTICAL', 'KNOWN', 'DIFF', 'MISSING', 'EXTRA'].filter((k) => v[k]).map((k) => `${v[k]} ${k}`).join(' + '));
  const gf = add(pick(/^graph fidelity: (clean|layered|nestjs|hexagonal|ddd)/));
  out['d-audit-smoke-gf-outputs'] = `${tot(gf)} files`;
  out['d-audit-smoke-gf-result'] = verdict(gf) === 'IDENTICAL' ? 'IDENTICAL, across two fresh exports' : verdict(gf);
  const gfa = add(pick(/^graph fidelity: re-aggregate/));
  out['d-audit-smoke-gfagg-outputs'] = String(tot(gfa));
  out['d-audit-smoke-gfagg-result'] = verdict(gfa);
  const im = add(pick(/^ISE measure/)); const id = add(pick(/^ISE downstream/)); const ie = add(pick(/^ISE E1 report/));
  out['d-audit-smoke-ise-outputs'] = `${tot(im)} + ${tot(id)} + ${tot(ie)}`;
  out['d-audit-smoke-ise-result'] = [im, id, ie].every((v) => verdict(v) === 'IDENTICAL') ? 'IDENTICAL' : [im, id, ie].map(verdict).join(' / ');
  const a72 = add(pick(/^APG v2 ablation @72fa9203/)); const ah = add(pick(/^APG v2 ablation$/));
  out['d-audit-smoke-apg2-outputs'] = `${tot(a72)} / ${tot(ah)}`;
  out['d-audit-smoke-apg2-result'] = `${verdict(a72) === 'IDENTICAL' ? `${a72.IDENTICAL} IDENTICAL` : verdict(a72)} / ${verdict(ah)} (C-1)`;
  const ch = add(pick(/^cheap proxies: evaluate/));
  out['d-audit-smoke-cheap-outputs'] = String(tot(ch));
  const stripped = /IDENTICAL results\/v1\.3-cheap-semantics\/scores\.json\[timings stripped\]/.test(log);
  out['d-audit-smoke-cheap-result'] = verdict(ch) === 'IDENTICAL' && stripped ? 'IDENTICAL; `scores.json` compared without wall-clock fields' : verdict(ch);
  // judge: everything after the first judge header (the last section also holds the round-1/2 comparisons)
  const jl = log.slice(log.indexOf('== judge catch round 1')).split('\n').filter((l) => /^(IDENTICAL|KNOWN|DIFF|MISSING|EXTRA)\s/.test(l));
  const strip = jl.filter((l) => /\[AP-DUP-RULE2 stripped\]/.test(l));
  const main = jl.filter((l) => !/\[AP-DUP-RULE2 stripped\]/.test(l));
  out['d-audit-smoke-judge-outputs'] = `${main.length} + ${strip.length} stripped`;
  const kn = main.filter((l) => l.startsWith('KNOWN')).length;
  const okMain = main.every((l) => /^(IDENTICAL|KNOWN)/.test(l)) && strip.every((l) => l.startsWith('IDENTICAL'));
  out['d-audit-smoke-judge-result'] = okMain ? `IDENTICAL + ${kn} KNOWN (D-5), which are IDENTICAL once the empty AP-DUP-RULE2 blocks are stripped` : 'differs';
  return out;
}

